def generate():
    all_keys = set(SVG_DEFINITIONS.keys()).union(svg_names)
    count = 0
    for name in all_keys:
        inner = SVG_DEFINITIONS.get(name, '<circle cx="12" cy="12" r="10"></circle>')
        full_svg = (
            '<?xml version="1.0" encoding="utf-8"?>\n'
            '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" '
            'fill="none" stroke="#f1f5f9" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">\n'
            f'  {inner}\n'
            '</svg>\n'
        )
        path = os.path.join(ICONS_DIR, f"{name}.svg")
        with open(path, "w", encoding="utf-8") as f:
            f.write(full_svg)
        count += 1
    print(f"Generated {count} fully compliant standalone SVGs in {ICONS_DIR}")

if __name__ == "__main__":
    generate()
